Lemma acc_full_granules : forall (m : mem) beg size, acc asegs m beg size -> (0 <= beg)%Z -> (0 <= size)%Z ->
  (beg + size <= 2^60)%Z ->
  bytes_at asegs m (shad ((beg + 7) / 8 * 8))
    (repeat z8 (Z.to_nat (shad ((beg + size) / 8 * 8) - shad ((beg + 7) / 8 * 8)))).
Proof.
